    // Convenience constants
    // -------------------------------------------------------------------------
    mov.u32 %r4, %ntid.x;                // blockDim.x (should be 256)
    // constant for converting exp(x) = 2^(x * log2(e))
    const.f32 %f10, 1.4426950408889634; // 1/ln(2)

    // -------------------------------------------------------------------------
    // -------------------------------------------------------------------------
    // 1) Compute the maximum value of the row (in fp32)
    // -------------------------------------------------------------------------
    // Initialize local max to -FLT_MAX
    mov.f32 %f0, -3.402823466e38;        // -FLT_MAX

